1	package factmerge
2	
3	import (
4		"errors"
5		"time"
6	)
7	
8	// errStaleProposal is returned when a proposal references a fact that no longer
9	// exists or is no longer active.
10	var errStaleProposal = errors.New("proposal references a missing or inactive fact")
11	
12	// removeFactByID returns facts with the record of the given id removed.
13	func removeFactByID(facts []Record, id string) []Record {
14		out := facts[:0:0]
15		for _, f := range facts {
16			if f.ID != id {
17				out = append(out, f)
18			}
19		}
20		return out
21	}
22	
23	// ApplyProposal resolves a queued proposal by performing its merge/supersede.
24	// Merge consolidates the candidate's provenance into the target and removes the
25	// now-redundant candidate record; supersede marks the target superseded by the
26	// candidate, which stays active. Both records must be distinct and active.
27	func ApplyProposal(facts []Record, p Proposal, now time.Time) ([]Record, error) {
28		ci := IndexOf(facts, p.CandidateID)
29		ti := IndexOf(facts, p.TargetID)
30		if ci < 0 || ti < 0 || facts[ci].Status != StatusActive || facts[ti].Status != StatusActive {
31			return facts, errStaleProposal
32		}
33		if ci == ti {
34			return facts, errors.New("proposal must reference two distinct facts")
35		}
36		if p.Action != ActionMerge && p.Action != ActionSupersede {
37			return facts, errors.New("proposal action must be merge or supersede")
38		}
39		facts = clearConflictLink(facts, p.CandidateID, p.TargetID)
40		ci = IndexOf(facts, p.CandidateID)
41		ti = IndexOf(facts, p.TargetID)
42		if p.Action == ActionMerge {
43			facts[ti].Provenance = UnionAnchors(facts[ti].Provenance, facts[ci].Provenance)
44			facts[ti].UpdatedAt = now
45			return removeFactByID(facts, p.CandidateID), nil
46		}
47		// supersede
48		facts[ti].Status = StatusSuperseded
49		facts[ti].SupersededBy = facts[ci].ID
50		facts[ti].UpdatedAt = now
51		return facts, nil
52	}
53	
54	// RejectProposal discards a proposal without changing fact status, removing the
55	// conflict cross-link so the pair is no longer flagged as conflicting.
56	func RejectProposal(facts []Record, p Proposal) []Record {
57		return clearConflictLink(facts, p.CandidateID, p.TargetID)
58	}
59	
60	// clearConflictLink removes the RelatedIDs cross-link between two facts.
61	func clearConflictLink(facts []Record, aID, bID string) []Record {
62		for i := range facts {
63			switch facts[i].ID {
64			case aID:
65				facts[i].RelatedIDs = removeString(facts[i].RelatedIDs, bID)
66			case bID:
67				facts[i].RelatedIDs = removeString(facts[i].RelatedIDs, aID)
68			}
69		}
70		return facts
71	}
72	
73	func removeString(values []string, target string) []string {
74		out := values[:0:0]
75		for _, v := range values {
76			if v != target {
77				out = append(out, v)
78			}
79		}
80		return out
81	}
82	
83	// Promote carries a source branch's active facts into a target set under
84	// the given strategy, returning the merged set, any conflict proposals queued
85	// (keep-both), and the number of facts promoted.
86	//
87	//   - keep-both: copy source facts in; a same-path conflict with an existing
88	//     active target fact keeps both, cross-links them, and queues a proposal.
