func TestRejectProposalKeepsBothActive(t *testing.T) {
	now := time.Date(2026, 6, 5, 12, 0, 0, 0, time.UTC)
	a := factFor(t, "a", []string{"project.tooling.stack"}, now)
	b := factFor(t, "b", []string{"project.tooling.stack"}, now)
