107	// TestFactsPromoteAcceptsADeletedBranchThatStillHasFacts pins the reason the
108	// endpoint check is "git knows it OR the brain has facts for it" rather than
109	// git alone: carrying a merged-and-deleted feature branch's facts forward is a
110	// normal use of promote, and a git-only check would have broken it.
111	func TestFactsPromoteAcceptsADeletedBranchThatStillHasFacts(t *testing.T) {
112		f := newVerifyFixture(t)
113		gitKnowsBranches(f, "main") // "shipped" was deleted after its merge
114		paths := normalizeFactPaths([]string{"ops.deploy.strategy"})
115		fact := factRecord{
116			ID: factRecordID("deploys use blue-green cutover", paths), Paths: paths,
117			Text: "deploys use blue-green cutover", Branch: "shipped", Origin: factstore.OriginDistilled,
118			Status: factStatusActive, CreatedAt: f.now, UpdatedAt: f.now,
119		}
120		f.writeFacts(t, "shipped", []factRecord{fact})
121	
122		out, err := execute(t, NewRootCommand(f.opts), "facts", "promote", "--from", "shipped", "--strategy", "keep-both")
123		if err != nil {
124			t.Fatalf("promote from a deleted branch that still has facts was refused: %v\n%s", err, out)
125		}
126		facts, loadErr := factstore.Load(f.storage.BrainDir, "main")
127		if loadErr != nil {
128			t.Fatal(loadErr)
129		}
130		if indexOfFact(facts, fact.ID) < 0 {
131			t.Fatalf("fact from the deleted branch did not land on main: %+v", facts)
132		}
