	for i := range facts {
		if facts[i].Status != StatusActive || facts[i].ID == candidate.ID {
			continue
		}
		for _, p := range facts[i].Paths {
			if _, ok := paths[p]; ok {
				idx = append(idx, i)
				break
			}
		}
	}
	return idx
}

// GCResult reports the outcome of a garbage-collection pass.
type GCResult struct {
	Kept    []Record
	Pruned  []Record
